window.__ModuleLoader__.load({ id: 'dsh-gundam-graphite-theme', factory: (require) => {
// config.js
const PLUGIN_ID = 'dsh-gundam-graphite-theme'
const FIELDS = Object.freeze({
  themeEnabled: { label: '启用石墨皮肤', default: true },
  motionEnabled: { label: '动效总开关', default: true },
  fluidEnabled: { label: '流体与粒子', default: true },
  gridEnabled: { label: '鼠标弹性网络', default: true },
  parallaxEnabled: { label: '壁纸景深视差', default: true },
  particleMode: { label: '粒子流动类型', default: 'flow', options: { flow: '流场', vortex: '涡旋', shower: '星雨' } },
  gridMode: { label: '网络交互模式', default: 'repel', options: { repel: '排斥回弹', attract: '吸引回弹', ripple: '涟漪扩散', swirl: '旋涡扭转', pulse: '呼吸脉冲' } },
  wallpaperDim: { label: '壁纸遮罩', default: 0.4, min: 0, max: 0.85, step: 0.01, unit: '%' },
  wallpaperBlur: { label: '壁纸虚化', default: 6, min: 0, max: 16, step: 1, unit: 'px' },
  surfaceOpacity: { label: '面板不透明度', default: 0.86, min: 0.6, max: 1, step: 0.01, unit: '%' },
  fluidIntensity: { label: '流体亮度', default: 0.4, min: 0, max: 1, step: 0.01, unit: '%' },
  particleDensity: { label: '粒子数量', default: 100, min: 20, max: 240, step: 10 },
  flowSpeed: { label: '流动速度', default: 0.65, min: 0.15, max: 2, step: 0.05, unit: '×' },
  gridStrength: { label: '网络弹性强度', default: 0.5, min: 0, max: 1, step: 0.05, unit: '%' },
  gridRadius: { label: '鼠标影响半径', default: 180, min: 80, max: 320, step: 10, unit: 'px' },
  fps: { label: '动效帧率上限', default: 30, min: 20, max: 60, step: 10, unit: 'fps' },
})
const DEFAULT_SETTINGS = Object.freeze(Object.fromEntries(
  Object.entries(FIELDS).map(([key, field]) => [key, field.default])
))
function normalizeSettings(value) {
  return Object.freeze(Object.fromEntries(Object.entries(FIELDS).map(([key, field]) => {
    const input = value?.[key]
    if (typeof field.default === 'boolean') return [key, typeof input === 'boolean' ? input : field.default]
    if (field.options) return [key, Object.hasOwn(field.options, input) ? input : field.default]
    return [key, typeof input === 'number' && Number.isFinite(input)
      ? Math.min(field.max, Math.max(field.min, input)) : field.default]
  })))
}

// client/physics.js
// Smooth time-varying vector field; particles integrate velocity through it.
function flowAt(x, y, time) {
  const angle = Math.sin(x * 0.0032 + time * 0.18) * 1.7
    + Math.cos(y * 0.004 - time * 0.13) * 1.3
    + Math.sin((x + y) * 0.002 + time * 0.09)
  return { x: Math.cos(angle) * 23 + 9, y: Math.sin(angle) * 20 - 7 }
}

function particleVelocity(x, y, time, mode, width, height) {
  if (mode === 'vortex') {
    const dx = x - width / 2, dy = y - height / 2
    const distance = Math.max(60, Math.hypot(dx, dy))
    return { x: (-dy * 34 + dx * 4) / distance, y: (dx * 34 + dy * 4) / distance }
  }
  if (mode === 'shower') return { x: -32 + Math.sin(y * 0.01 + time) * 4, y: 48 }
  return flowAt(x, y, time)
}

function stepSpring(node, pointer, radius, strength, dt, mode = 'repel', time = 0) {
  let tx = node.ax, ty = node.ay
  if (pointer.active && strength > 0) {
    const dx = node.ax - pointer.x, dy = node.ay - pointer.y
    const distance = Math.hypot(dx, dy)
    if (distance < radius) {
      const ux = distance > 0.01 ? dx / distance : 1
      const uy = distance > 0.01 ? dy / distance : 0
      const falloff = 1 - distance / radius
      let offset = falloff ** 2 * 65 * strength
      if (mode === 'attract') offset *= -1
      if (mode === 'ripple') offset = Math.sin(distance / radius * Math.PI * 4 - time * 7) * falloff * 50 * strength
      if (mode === 'pulse') offset *= Math.sin(time * 5)
      if (mode === 'swirl') { tx -= uy * offset; ty += ux * offset }
      else { tx += ux * offset; ty += uy * offset }
    }
  }
  // Substeps make a 20 fps cap behave like a 60 fps spring, including on resume.
  const steps = Math.max(1, Math.ceil(dt / (1 / 120)))
  const h = Math.min(dt, 0.05) / steps
  for (let i = 0; i < steps; i++) {
    node.vx += ((tx - node.x) * 95 - node.vx * 12) * h
    node.vy += ((ty - node.y) * 95 - node.vy * 12) * h
    node.x += node.vx * h
    node.y += node.vy * h
  }
}

// client/effects.js

function createEffects(layer, initial, art) {
  let settings = initial, width = 1, height = 1, raf = 0, last = 0, time = 0, networkTime = 0, disposed = false
  let particles = [], sparks = [], sparkDelay = 0, nodes = [], columns = 0, density = 0
  const pointer = { x: 0, y: 0, active: false }
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)')
  const coarse = window.matchMedia('(pointer: coarse)')
  const canvases = ['fluid', 'particles', 'network'].map(name => {
    const canvas = document.createElement('canvas')
    canvas.className = `gg-${name}`
    canvas.setAttribute('aria-hidden', 'true')
    layer.appendChild(canvas)
    return canvas
  })
  const contexts = canvases.map(canvas => canvas.getContext('2d'))
  const [haze, trail, grid] = contexts
  const clear = () => contexts.forEach(ctx => ctx?.clearRect(0, 0, width, height))
  const fluidOn = () => settings.fluidEnabled && settings.fluidIntensity > 0
  const gridOn = () => settings.gridEnabled && !coarse.matches
  const active = () => !disposed && contexts.every(Boolean) && settings.themeEnabled
    && settings.motionEnabled && !reduced.matches && !document.hidden && (fluidOn() || gridOn())
  const parallaxOn = () => !disposed && settings.themeEnabled && settings.motionEnabled && settings.parallaxEnabled && !reduced.matches && !document.hidden

  function syncParallax() {
    const enabled = parallaxOn()
    layer.dataset.parallax = enabled ? 'running' : 'paused'
    const x = pointer.active && enabled ? Math.max(-1, Math.min(1, pointer.x / width * 2 - 1)) : 0
    const y = pointer.active && enabled ? Math.max(-1, Math.min(1, pointer.y / height * 2 - 1)) : 0
    layer.style.setProperty('--gg-far-x', `${(-x * 3).toFixed(1)}px`)
    layer.style.setProperty('--gg-far-y', `${(-y * 2).toFixed(1)}px`)
    layer.style.setProperty('--gg-near-x', `${(x * 3).toFixed(1)}px`)
    layer.style.setProperty('--gg-near-y', `${(y * 2).toFixed(1)}px`)
  }

  function seed() {
    density = Math.max(12, Math.round(settings.particleDensity * Math.min(1.5, width * height / 1100000)))
    particles = Array.from({ length: density }, () => ({ x: Math.random() * width, y: Math.random() * height, age: Math.random() * 12, size: 0.5 + Math.random() }))
  }
  function resize() {
    width = Math.max(1, window.innerWidth)
    height = Math.max(1, window.innerHeight)
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5, 4096 / Math.max(width, height))
    canvases.forEach((canvas, i) => {
      canvas.width = Math.round(width * dpr)
      canvas.height = Math.round(height * dpr)
      contexts[i]?.setTransform(dpr, 0, 0, dpr, 0, 0)
    })
    // Bound the mesh to roughly 600 nodes, including ultrawide desktops.
    const spacing = Math.max(68, Math.sqrt(width * height / 600))
    columns = Math.ceil(width / spacing) + 1
    const rows = Math.ceil(height / spacing) + 1
    nodes = Array.from({ length: columns * rows }, (_, i) => {
      const x = (i % columns) * spacing, y = Math.floor(i / columns) * spacing
      return { ax: x, ay: y, x, y, vx: 0, vy: 0 }
    })
    seed(); sparks = []; sparkDelay = 0; syncParallax()
  }
  function drawSparks(dt) {
    sparkDelay -= dt
    if (sparkDelay <= 0) {
      const rect = art.getBoundingClientRect()
      const source = [[0.645, 0.32], [0.798, 0.604], [0.666, 0.755]][Math.floor(Math.random() * 3)]
      for (let i = 0; i < 2; i++) sparks.push({
        x: rect.left + rect.width * source[0] + (Math.random() - 0.5) * 18,
        y: rect.top + rect.height * source[1] + (Math.random() - 0.5) * 18,
        vx: -12 - Math.random() * 18, vy: -16 - Math.random() * 30,
        life: 0.8 + Math.random() * 0.6, age: 0, size: 0.5 + Math.random(),
      })
      sparkDelay = 2 + Math.random() * 2
    }
    sparks = sparks.filter(spark => spark.age + dt < spark.life)
    for (const spark of sparks) {
      const x = spark.x, y = spark.y
      spark.x += spark.vx * dt; spark.y += spark.vy * dt; spark.age += dt
      const alpha = Math.min(1, spark.age * 5, (spark.life - spark.age) * 3) * settings.fluidIntensity * 0.75
      trail.strokeStyle = `rgba(255,77,65,${alpha * 0.5})`
      trail.beginPath(); trail.moveTo(x, y); trail.lineTo(spark.x, spark.y); trail.stroke()
      trail.fillStyle = `rgba(255,104,83,${alpha})`
      trail.beginPath(); trail.arc(spark.x, spark.y, spark.size, 0, Math.PI * 2); trail.fill()
    }
  }
  function drawFluid(dt) {
    haze.clearRect(0, 0, width, height)
    if (!fluidOn()) { trail.clearRect(0, 0, width, height); return }
    const intensity = settings.fluidIntensity
    for (let i = 0; i < 3; i++) {
      const x = width * (0.2 + i * 0.27) + Math.sin(time * 0.13 + i * 2) * width * 0.12
      const y = height * (0.5 + Math.cos(time * 0.12 + i * 2) * 0.25)
      const radius = Math.max(width, height) * 0.33
      const gradient = haze.createRadialGradient(x, y, 0, x, y, radius)
      gradient.addColorStop(0, `rgba(158,170,184,${intensity * 0.10})`)
      gradient.addColorStop(0.45, `rgba(110,121,138,${intensity * 0.04})`)
      gradient.addColorStop(1, 'rgba(110,121,138,0)')
      haze.fillStyle = gradient
      haze.fillRect(0, 0, width, height)
    }
    trail.globalCompositeOperation = 'destination-out'
    trail.fillStyle = `rgba(0,0,0,${1 - Math.exp(-dt * 4)})`
    trail.fillRect(0, 0, width, height)
    trail.globalCompositeOperation = 'source-over'
    trail.lineWidth = 0.7
    for (const p of particles) {
      const previousX = p.x, previousY = p.y
      const velocity = particleVelocity(p.x, p.y, time, settings.particleMode, width, height)
      p.x += velocity.x * dt * settings.flowSpeed
      p.y += velocity.y * dt * settings.flowSpeed
      p.age += dt
      if (p.x < -10 || p.x > width + 10 || p.y < -10 || p.y > height + 10 || p.age > 18) {
        p.x = Math.random() * width; p.y = Math.random() * height; p.age = 0
        continue
      }
      const fade = Math.min(1, p.age, 18 - p.age)
      trail.strokeStyle = `rgba(187,196,208,${0.55 * intensity * fade})`
      trail.beginPath(); trail.moveTo(previousX, previousY); trail.lineTo(p.x, p.y); trail.stroke()
      trail.fillStyle = `rgba(224,230,238,${0.42 * intensity * fade})`
      trail.beginPath(); trail.arc(p.x, p.y, p.size, 0, Math.PI * 2); trail.fill()
    }
    drawSparks(dt)
  }
  function drawGrid(dt) {
    grid.clearRect(0, 0, width, height)
    if (!gridOn()) return
    nodes.forEach(node => stepSpring(node, pointer, settings.gridRadius, settings.gridStrength, dt, settings.gridMode, networkTime))
    grid.lineWidth = 0.65
    for (let i = 0; i < nodes.length; i++) {
      const n = nodes[i]
      const proximity = pointer.active ? Math.max(0, 1 - Math.hypot(n.ax - pointer.x, n.ay - pointer.y) / (settings.gridRadius * 1.5)) : 0
      const stretch = Math.min(1, Math.hypot(n.x - n.ax, n.y - n.ay) / 20)
      const alpha = 0.018 + Math.max(proximity, stretch) * 0.19
      grid.strokeStyle = `rgba(197,206,217,${alpha})`
      grid.beginPath()
      if (i % columns < columns - 1) { const next = nodes[i + 1]; grid.moveTo(n.x, n.y); grid.lineTo(next.x, next.y) }
      if (i + columns < nodes.length) { const next = nodes[i + columns]; grid.moveTo(n.x, n.y); grid.lineTo(next.x, next.y) }
      grid.stroke()
      if (proximity > 0.15 || stretch > 0.1) {
        grid.fillStyle = `rgba(225,231,238,${alpha * 1.7})`
        grid.fillRect(n.x - 1, n.y - 1, 2, 2)
      }
    }
  }
  function frame(now) {
    raf = 0
    if (!active()) return
    if (!last) last = now - 1000 / settings.fps
    const elapsed = now - last
    if (elapsed + 0.5 >= 1000 / settings.fps) {
      const dt = Math.min(elapsed / 1000, 0.05)
      last = now; time += dt * settings.flowSpeed; networkTime += dt
      drawFluid(dt); drawGrid(dt)
    }
    raf = window.requestAnimationFrame(frame)
  }
  function sync() {
    if (raf) window.cancelAnimationFrame(raf)
    raf = 0; last = 0
    clear()
    if (!active() || !fluidOn()) { sparks = []; sparkDelay = 0 }
    syncParallax()
    layer.dataset.motion = active() ? 'running' : 'paused'
    if (active()) raf = window.requestAnimationFrame(frame)
  }
  const move = event => {
    if (event.pointerType === 'touch') return
    pointer.x = event.clientX; pointer.y = event.clientY; pointer.active = true
    syncParallax()
  }
  const leave = () => { pointer.active = false; syncParallax() }
  const visibility = () => { leave(); sync() }
  window.addEventListener('pointermove', move, { passive: true })
  document.documentElement.addEventListener('pointerleave', leave, { passive: true })
  window.addEventListener('blur', leave)
  window.addEventListener('resize', resize)
  document.addEventListener('visibilitychange', visibility)
  reduced.addEventListener('change', sync)
  coarse.addEventListener('change', sync)
  resize(); sync()
  return {
    update(next) {
      const reseed = next.particleDensity !== settings.particleDensity
      settings = next
      if (reseed) seed()
      sync()
    },
    destroy() {
      disposed = true
      if (raf) window.cancelAnimationFrame(raf)
      window.removeEventListener('pointermove', move)
      document.documentElement.removeEventListener('pointerleave', leave)
      window.removeEventListener('blur', leave)
      window.removeEventListener('resize', resize)
      document.removeEventListener('visibilitychange', visibility)
      reduced.removeEventListener('change', sync)
      coarse.removeEventListener('change', sync)
      canvases.forEach(canvas => { canvas.width = 1; canvas.height = 1; canvas.remove() })
      for (const name of ['--gg-far-x', '--gg-far-y', '--gg-near-x', '--gg-near-y']) layer.style.removeProperty(name)
      nodes = []; particles = []; sparks = []
    },
  }
}

// client/theme.js
function graphiteTokens(opacity) {
  const surface = `rgba(19,22,27,${opacity})`
  const values = {
    '--dsw-alias-bg-base': '#0c0e12',
    '--dsw-alias-bg-layer-1': surface,
    '--dsw-alias-bg-layer-2': '#1c2027',
    '--dsw-alias-bg-layer-3': '#262c35',
    '--dsw-alias-bg-module-platform': '#20252c',
    '--dsw-alias-bg-overlay': '#20242b',
    '--dsw-alias-bg-mask-1': 'rgba(0,0,0,0.72)',
    '--dsw-alias-bg-mask-2': 'rgba(0,0,0,0.5)',
    '--dsw-alias-border-l1': 'rgba(218,226,237,0.09)',
    '--dsw-alias-border-l2': 'rgba(218,226,237,0.15)',
    '--dsw-alias-border-l3': 'rgba(218,226,237,0.21)',
    '--dsw-alias-border-l4': 'rgba(218,226,237,0.3)',
    '--dsw-alias-brand-primary': '#c6cdd8',
    '--dsw-alias-brand-primary-new-colorprimary-new-color': '#c6cdd8',
    '--dsw-alias-brand-text': '#dce2eb',
    '--dsw-alias-label-primary': '#eceff4',
    '--dsw-alias-label-primary-inverted': '#12151a',
    '--dsw-alias-label-secondary': '#bbc2cd',
    '--dsw-alias-label-tertiary': '#939daa',
    '--dsw-alias-label-caption': '#a0a9b7',
    '--dsw-alias-markdown-code-block-banner': '#15191f',
    '--dsw-alias-state-business-primary': '#c6cdd8',
    '--dsw-alias-state-business-tertiary': 'rgba(197,207,224,0.16)',
    '--dsw-alias-button-primary-fill': '#b8c1cf',
    '--dsw-alias-button-primary-hover': '#d2d9e3',
    '--dsw-alias-button-info-fill': '#515e70',
    '--dsw-alias-button-info-hover': '#65758b',
    '--dsw-alias-button-elevated-fill': '#2a303a',
    '--dsw-alias-button-floating-fill': '#252a32',
    '--dsw-alias-button-floating-hover': '#363d48',
    '--dsw-alias-interactive-bg-hover': 'rgba(218,226,237,0.08)',
    '--dsw-alias-interactive-bg-active': 'rgba(218,226,237,0.14)',
    '--dsw-alias-interactive-bg-hover-solid': '#2c333d',
    '--dsw-alias-scrollbar-bg-l1': '#353d49',
    '--dsw-alias-scrollbar-bg-l2': '#46505e',
    '--dsw-alias-scrollbar-hover-l1': '#626d7e',
    '--dsw-alias-scrollbar-hover-l2': '#7b8798',
    '--dsw-alias-tooltip-bg': '#272c34',
    '--dsw-alias-toast-bg': '#252b33',
    '--dsw-specific-bubble': surface,
    '--dsw-specific-bubble-highlight': '#343c49',
    '--dsw-specific-sidebar-fill': `rgba(12,14,18,${opacity})`,
    '--dsw-specific-selector': '#252b34',
    '--dsw-specific-tip': '#20262f',
  }
  return Object.fromEntries(Object.entries(values).map(([key, value]) => [key, { light: value, dark: value }]))
}

const THEME_CSS = `
html[data-gundam-graphite] { background: #0c0e12; color-scheme: dark !important; }
html[data-gundam-graphite] body { isolation: isolate; background: #0c0e12; color-scheme: dark !important; }
.gg-background { position: fixed; inset: 0; z-index: -1; overflow: hidden; pointer-events: none !important; user-select: none; }
.gg-background[hidden] { display: none; }
.gg-wallpaper { position: absolute; inset: -32px; }
/* The artboard matches background-size: cover for the 1672x941 image and 32px overscan. */
.gg-wallpaper-art { position: absolute; left: 72%; top: 50%; width: max(100%, calc(177.68vh + 114px)); aspect-ratio: 1672 / 941; transform: translate(-72%, -50%); background-image: url('data:image/png;base64,'); background-size: 0 0; }
.gg-wallpaper-art::before,.gg-wallpaper-art::after { content: ''; position: absolute; inset: 0; background-image: inherit; background-size: 100% 100%; }
.gg-wallpaper-art::before { z-index: 0; filter: blur(var(--gg-blur, 0px)); transform: translate3d(var(--gg-far-x, 0px), var(--gg-far-y, 0px), 0); transition: transform .28s ease-out; }
.gg-wallpaper-art::after { z-index: 1; -webkit-mask-image: linear-gradient(to right, transparent 38%, black 63%); mask-image: linear-gradient(to right, transparent 38%, black 63%); transform: translate3d(var(--gg-near-x, 0px), var(--gg-near-y, 0px), 0); transition: transform .28s ease-out; }
.gg-wallpaper-glow { position: absolute; inset: 0; z-index: 2; background: radial-gradient(ellipse 4% 3% at 64.5% 32%, rgba(255,38,52,.8), transparent), radial-gradient(ellipse 4% 4% at 79.8% 60.4%, rgba(255,31,46,.65), transparent), radial-gradient(ellipse 5% 3% at 66.6% 75.5%, rgba(255,37,49,.65), transparent); mix-blend-mode: screen; transform: translate3d(var(--gg-near-x, 0px), var(--gg-near-y, 0px), 0); transition: transform .28s ease-out; animation: gg-glow 5.8s ease-in-out infinite; }
.gg-wallpaper-shade { position: absolute; inset: 0; background: linear-gradient(to right, rgba(4,6,9,.42), rgba(4,6,9,.28) 30%, transparent 62%), rgba(4,6,9,var(--gg-dim)); }
.gg-background[data-glow='paused'] .gg-wallpaper-glow { animation: none; opacity: 0; }
.gg-background[data-parallax='paused'] .gg-wallpaper-art::before,.gg-background[data-parallax='paused'] .gg-wallpaper-art::after,.gg-background[data-parallax='paused'] .gg-wallpaper-glow { transition: none; }
@keyframes gg-glow { 0%,100% { opacity: .3; } 50% { opacity: .8; } }
@media (prefers-reduced-motion: reduce) { .gg-wallpaper-glow { animation: none; opacity: 0; } .gg-wallpaper-art::before,.gg-wallpaper-art::after,.gg-wallpaper-glow { transition: none; } }
.gg-background canvas { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none !important; }
html[data-gundam-graphite] #root,
html[data-gundam-graphite] [class$='_frame'],
html[data-gundam-graphite] [class*='_frame '],
html[data-gundam-graphite] [class$='_centerCol'],
html[data-gundam-graphite] [class*='_centerCol '],
html[data-gundam-graphite] [class$='_centerCol'] > [class$='_root'],
html[data-gundam-graphite] [class$='_centerCol'] [class$='_root']:has(> [class$='_body'] > [class$='_scrollBody']) { background-color: transparent !important; }
html[data-gundam-graphite] [class$='_sidebarCol'],
html[data-gundam-graphite] [data-rightbar-col] { background: rgba(12,14,18,var(--gg-surface)) !important; }
html[data-gundam-graphite] [data-composer-seat] [class$='_card'] { background: rgba(19,22,27,var(--gg-surface)); backdrop-filter: blur(12px); }
html[data-gundam-graphite] [class*='_markdown_'],
html[data-gundam-graphite] [class*='_flowItem'] { text-shadow: 0 1px 5px rgba(0,0,0,0.8); }
html[data-gundam-graphite] ::selection { background: #a9b5c7; color: #101319; }
.gg-settings { padding: 20px 0; border-bottom: 1px solid var(--dsw-alias-border-l2); color: var(--dsw-alias-label-primary); }
.gg-heading { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-bottom: 8px; }
.gg-heading strong { font-size: 16px; font-weight: 600; }
.gg-heading span { font-size: 10px; letter-spacing: .16em; opacity: .6; }
.gg-description { color: var(--dsw-alias-label-secondary); font-size: 12px; line-height: 1.7; margin: 0 0 16px; }
.gg-fields { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 12px 24px; }
.gg-control { display: flex; align-items: center; justify-content: space-between; gap: 12px; font-size: 13px; min-height: 28px; }
.gg-slider { display: grid; grid-template-columns: 1fr auto; gap: 8px; font-size: 12px; }
.gg-slider input { grid-column: 1 / -1; width: 100%; margin: 0; accent-color: #9daabb; }
.gg-control input { accent-color: #9daabb; width: 16px; height: 16px; }
.gg-choice { display: flex; align-items: center; justify-content: space-between; gap: 12px; font-size: 12px; }
.gg-choice select { min-width: 96px; padding: 5px 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-layer-2); color: var(--dsw-alias-label-primary); font: inherit; }
.gg-slider output { color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.gg-settings input:disabled,.gg-settings select:disabled { opacity: .4; }
.gg-settings input:focus-visible,.gg-settings select:focus-visible,.gg-settings button:focus-visible { outline: 2px solid #a9b9d1; outline-offset: 4px; }
.gg-status { font-size: 12px; color: var(--dsw-alias-label-secondary); margin-top: 12px; }
.gg-reset { margin-top: 16px; background: var(--dsw-alias-bg-layer-2); color: var(--dsw-alias-label-primary); border: 1px solid var(--dsw-alias-border-l2); padding: 7px 12px; border-radius: 7px; font: inherit; font-size: 12px; cursor: pointer; }
@media(max-width:600px) { .gg-fields { grid-template-columns: minmax(0,1fr); } }
`

// client/settings.js
// Settings transport adapted from JohnnyTing (MIT); see THIRD_PARTY_NOTICES.md.

// Optional service children must not block the theme's root fiber at startup.
function createHostSettingsForm(ctx, entryId) {
  const listeners = new Set()
  const forms = new Map()
  const unavailable = Object.freeze({ status: 'unavailable', mode: 'host', writable: false })
  const current = () => forms.get('configForms') ?? forms.get('settingsScope')
  const notify = () => { for (const listener of listeners) listener() }
  const disposers = ['configForms', 'settingsScope'].map(service => ctx.inject([service], child => {
    child.effect(() => {
      const form = service === 'configForms'
        ? child.configForms.get(entryId)
        : child.settingsScope.bind({ namespace: entryId })
      forms.set(service, form)
      const off = form.subscribe(notify)
      notify()
      return () => {
        off()
        forms.delete(service)
        notify()
      }
    })
  }))
  return {
    getSnapshot: () => current()?.getSnapshot() ?? unavailable,
    subscribe: listener => { listeners.add(listener); return () => listeners.delete(listener) },
    mutate: ops => current()?.mutate(ops) ?? Promise.resolve(false),
    destroy: () => { listeners.clear(); return Promise.all(disposers.map(fiber => fiber.dispose())) },
  }
}

// The host owns persistence, revision checks and reconnect synchronization.
// Never seed its config from browser storage or write defaults during loading.
function createSettingsController(form) {
  const listeners = new Set()
  let saving = false
  let generation = 0
  let preview
  let error = ''
  let disposed = false
  let snapshot
  const sync = () => {
    if (disposed) return
    const host = form.getSnapshot()
    const ready = host.status === 'ready' && host.value !== undefined
    snapshot = Object.freeze({
      value: preview ?? normalizeSettings(ready ? host.value : DEFAULT_SETTINGS),
      ready,
      loading: host.status === 'loading',
      editable: ready && (host.mode ?? 'host') === 'host' && host.writable,
      saving,
      error,
    })
    for (const listener of listeners) listener()
  }
  const unsubscribe = form.subscribe(sync)
  sync()

  return {
    get: () => snapshot,
    subscribe: listener => {
      listeners.add(listener)
      return () => { listeners.delete(listener) }
    },
    set: async update => {
      if (disposed || !snapshot.editable) return false
      const fields = Object.keys(DEFAULT_SETTINGS).filter(field => Object.hasOwn(update, field))
      if (fields.length === 0) return false
      preview = normalizeSettings({ ...snapshot.value, ...update })
      const ops = fields.map(field => ({ op: 'set', path: [field], value: preview[field] }))
      const current = ++generation
      saving = true
      error = ''
      sync()
      try {
        const accepted = await form.mutate(ops)
        if (!accepted && current === generation) error = '设置保存失败，请重试。'
        return accepted
      } catch {
        if (current === generation) error = '设置保存失败，请检查连接后重试。'
        return false
      } finally {
        if (current === generation) {
          preview = undefined
          saving = false
          sync()
        }
      }
    },
    destroy: () => {
      disposed = true
      unsubscribe()
      listeners.clear()
    },
  }
}


// client/index.js

const inject = ['slots', 'theme']

function GraphiteSettings({ controller }) {
  const React = require('react')
  const h = React.createElement
  const state = React.useSyncExternalStore(controller.subscribe, controller.get, controller.get)
  const settings = state.value
  const controls = Object.entries(FIELDS).map(([key, field]) => {
    const boolean = typeof field.default === 'boolean'
    const effectField = ['particleMode', 'gridMode', 'fluidIntensity', 'particleDensity', 'flowSpeed', 'gridStrength', 'gridRadius', 'fps'].includes(key)
    const disabled = !state.editable || (key !== 'themeEnabled' && !settings.themeEnabled)
      || (effectField && !settings.motionEnabled)
      || (['particleMode', 'fluidIntensity', 'particleDensity', 'flowSpeed'].includes(key) && !settings.fluidEnabled)
      || (['gridMode', 'gridStrength', 'gridRadius'].includes(key) && !settings.gridEnabled)
    if (field.options) return h('label', { key, className: 'gg-choice' },
      h('span', null, field.label),
      h('select', { 'aria-label': field.label, value: settings[key], disabled,
        onChange: event => { void controller.set({ [key]: event.target.value }) },
      }, Object.entries(field.options).map(([value, label]) => h('option', { key: value, value }, label))))
    const display = field.unit === '%' ? `${Math.round(settings[key] * 100)}%`
      : `${Number(settings[key].toFixed?.(2) ?? settings[key])}${field.unit || ''}`
    return h('label', { key, className: boolean ? 'gg-control' : 'gg-slider' },
      h('span', null, field.label),
      boolean ? null : h('output', null, display),
      h('input', {
        type: boolean ? 'checkbox' : 'range',
        'aria-label': field.label, disabled,
        ...(boolean ? { checked: settings[key] } : { value: settings[key], min: field.min, max: field.max, step: field.step }),
        onChange: event => { void controller.set({ [key]: boolean ? event.target.checked : Number(event.target.value) }) },
      })
    )
  })
  const message = state.error || (state.saving ? '正在保存…' : state.loading ? '正在读取设置…' : !state.editable ? '设置暂不可用，请等待 DSH 连接完成。' : '设置自动保存；系统减少动态效果开启时，动效暂停。')
  return h('section', { className: 'gg-settings', 'aria-label': '高达·石墨主题设置' },
    h('div', { className: 'gg-heading' }, h('strong', null, '高达 · 石墨'), h('span', null, 'GUNDAM / GRAPHITE')),
    h('p', { className: 'gg-description' }, '黑灰机甲壁纸，遮罩与虚化可调。动效关闭后保留静态壁纸。'),
    h('div', { className: 'gg-fields' }, controls),
    h('div', { className: 'gg-status', role: state.error ? 'alert' : 'status' }, message),
    h('button', { className: 'gg-reset', type: 'button', disabled: !state.editable, onClick: () => { void controller.set(DEFAULT_SETTINGS) } }, '恢复默认')
  )
}

function apply(ctx) {
  if (typeof document === 'undefined' || typeof window === 'undefined') return
  ctx.effect(() => {
    const root = document.documentElement
    const style = document.createElement('style')
    style.dataset.plugin = PLUGIN_ID
    style.textContent = THEME_CSS
    document.head.appendChild(style)
    const layer = document.createElement('div')
    layer.className = 'gg-background'
    layer.setAttribute('aria-hidden', 'true')
    const wallpaper = document.createElement('div')
    wallpaper.className = 'gg-wallpaper'
    const art = document.createElement('div')
    art.className = 'gg-wallpaper-art'
    const glow = document.createElement('div')
    glow.className = 'gg-wallpaper-glow'
    art.appendChild(glow)
    wallpaper.appendChild(art)
    layer.appendChild(wallpaper)
    const shade = document.createElement('div')
    shade.className = 'gg-wallpaper-shade'
    layer.appendChild(shade)
    document.body.prepend(layer)
    const form = createHostSettingsForm(ctx, PLUGIN_ID)
    const controller = createSettingsController(form)
    const effects = createEffects(layer, controller.get().value, art)
    let stopTokens, enabled = false, lastOpacity, disposed = false
    const restorePalette = () => document.body.toggleAttribute('data-ds-dark-theme', ctx.theme.getTheme().active.colorScheme === 'dark')
    // Temporary presentation only: never persist a replacement Appearance preference.
    const stopThemeListener = ctx.on('theme/change', () => {
      if (enabled) queueMicrotask(() => { if (!disposed && enabled) document.body.setAttribute('data-ds-dark-theme', '') })
    })
    const syncGlow = () => {
      const value = controller.get().value
      layer.dataset.glow = value.themeEnabled && value.motionEnabled && !document.hidden ? 'running' : 'paused'
    }
    document.addEventListener('visibilitychange', syncGlow)
    const sync = () => {
      const value = controller.get().value
      enabled = value.themeEnabled
      root.toggleAttribute('data-gundam-graphite', enabled)
      layer.hidden = !enabled
      syncGlow()
      if (enabled) {
        root.style.setProperty('--gg-dim', String(value.wallpaperDim))
        root.style.setProperty('--gg-blur', `${value.wallpaperBlur}px`)
        root.style.setProperty('--gg-surface', String(value.surfaceOpacity))
        if (!stopTokens || lastOpacity !== value.surfaceOpacity) {
          stopTokens?.()
          stopTokens = ctx.theme.overrideTokens(PLUGIN_ID, graphiteTokens(value.surfaceOpacity))
          lastOpacity = value.surfaceOpacity
        }
        document.body.setAttribute('data-ds-dark-theme', '')
      } else {
        stopTokens?.(); stopTokens = undefined
        root.style.removeProperty('--gg-dim')
        root.style.removeProperty('--gg-blur')
        root.style.removeProperty('--gg-surface')
        restorePalette()
      }
      effects.update(value)
    }
    const unsubscribe = controller.subscribe(sync)
    sync()
    ctx.slots.inject('settings.general.item', () => ctx.slots.register({
      name: 'settings.general.item', id: 'gundam-graphite-settings', order: 30,
      inject: () => ({ controller }),
    }, GraphiteSettings))
    return () => {
      disposed = true; enabled = false
      document.removeEventListener('visibilitychange', syncGlow)
      unsubscribe(); controller.destroy(); form.destroy(); effects.destroy()
      stopThemeListener(); stopTokens?.(); restorePalette()
      layer.remove(); style.remove()
      root.removeAttribute('data-gundam-graphite')
      root.style.removeProperty('--gg-dim'); root.style.removeProperty('--gg-blur'); root.style.removeProperty('--gg-surface')
    }
  }, 'Gundam Graphite theme and effects')
}

return { apply, inject };
} });
